/// Raven `BotStraightTPOrderCheck`.
///
/// `squadLeader` is a stored `*mut gentity_t` (bot_state_s.rs:63), so the
/// `squadLeader == ent` identity test is a direct pointer compare.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:128-155`
pub fn BotStraightTPOrderCheck(
    ent: *mut gentity_t,
    ordernum: c_int,
    bs: *mut bot_state_t,
) {
    unsafe {
        match ordernum {
            0 => {
                if (*bs).squadLeader == ent {
                    (*bs).teamplayState = 0;
                    (*bs).squadLeader = None;
                }
            }
            x if x == bot_teamplay_state_t::TEAMPLAYSTATE_FOLLOWING as c_int => {
                (*bs).teamplayState = ordernum;
                (*bs).isSquadLeader = 0;
                (*bs).squadLeader = ent;
                (*bs).wpDestSwitchTime = 0.0;
            }
            x if x == bot_teamplay_state_t::TEAMPLAYSTATE_ASSISTING as c_int => {
                (*bs).teamplayState = ordernum;
                (*bs).isSquadLeader = 0;
                (*bs).squadLeader = ent;
                (*bs).wpDestSwitchTime = 0.0;
            }
            _ => {
                (*bs).teamplayState = ordernum;
            }
        }
    }
}

