/// Raven `PlayersInGame`.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:793-812`
pub fn PlayersInGame(ctx: GameContext<'_>) -> c_int {
    unsafe {
        let world = &*ctx.world;
        let mut i: usize = 0;
        let mut pl = 0;
        while i < MAX_CLIENTS {
            let ent = &world.entities[i];
            if !ent.client.is_null()
                && (*(ent.client as *mut gclient_t)).pers.connected == CON_CONNECTED
            {
                pl += 1;
            }
            i += 1;
        }
        pl
    }
}

