/// Raven `BotResetState`.
///
/// `settings`/`cur_ps` are `Copy`, so the save/zero/restore mirrors Raven's
/// memcpy+memset+memcpy exactly.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:924-959`
pub fn BotResetState(
    ctx: GameContext<'_>,
    bs: *mut bot_state_t,
) {
    unsafe {
        // Save the things that must survive the reset.
        let settings = core::ptr::read(&(*bs).settings);
        let ps = core::ptr::read(&(*bs).cur_ps);
        let inuse = (*bs).inuse;
        let client = (*bs).client;
        let entitynum = (*bs).entitynum;
        let movestate = (*bs).ms;
        let goalstate = (*bs).gs;
        let weaponstate = (*bs).ws;
        let entergame_time = (*bs).entergame_time;
        // Reset the whole state.
        core::ptr::write_bytes(bs, 0, 1);
        // Copy back the preserved state.
        (*bs).ms = movestate;
        (*bs).gs = goalstate;
        (*bs).ws = weaponstate;
        core::ptr::write(&mut (*bs).cur_ps, ps);
        core::ptr::write(&mut (*bs).settings, settings);
        (*bs).inuse = inuse;
        (*bs).client = client;
        (*bs).entitynum = entitynum;
        (*bs).entergame_time = entergame_time;
        // Reset several engine-side states.
        if (*bs).ms != 0 {
            trap::BotResetMoveState(ctx.engine, BotlibAiResetMoveStateArgs::new((*bs).ms));
        }
        if (*bs).gs != 0 {
            trap::BotResetGoalState(ctx.engine, BotlibAiResetGoalStateArgs::new((*bs).gs));
        }
        if (*bs).ws != 0 {
            trap::BotResetWeaponState(ctx.engine, BotlibAiResetWeaponStateArgs::new((*bs).ws));
        }
        if (*bs).gs != 0 {
            trap::BotResetAvoidGoals(ctx.engine, BotlibAiResetAvoidGoalsArgs::new((*bs).gs));
        }
        if (*bs).ms != 0 {
            trap::BotResetAvoidReach(ctx.engine, BotlibAiResetAvoidReachArgs::new((*bs).ms));
        }
    }
}

