/// Raven `InFieldOfVision`.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:2034-2074`
pub fn InFieldOfVision(
    viewangles: vec3_t,
    fov: f32,
    mut angles: vec3_t,
) -> c_int {
    // Raven: 1 if `angles` lies within `fov` of `viewangles` (yaw+pitch only).
    for i in 0..2usize {
        let angle = crate::q_math::AngleMod(viewangles[i]);
        angles[i] = crate::q_math::AngleMod(angles[i]);
        let mut diff = angles[i] - angle;
        if angles[i] > angle {
            if diff > 180.0 {
                diff -= 360.0;
            }
        } else if diff < -180.0 {
            diff += 360.0;
        }
        if diff > 0.0 {
            if diff > fov * 0.5 {
                return 0;
            }
        } else if diff < -fov * 0.5 {
            return 0;
        }
    }
    1
}

