/// Raven `BotWeaponCanLead`.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:4570-4604`
pub fn BotWeaponCanLead(
    bs: *mut bot_state_t,
) -> f32 {
    let weap = unsafe { (*bs).cur_ps.weapon };
    if weap == WP_BRYAR_PISTOL {
        return 0.5;
    }
    if weap == WP_BLASTER {
        return 0.35;
    }
    if weap == WP_BOWCASTER {
        return 0.5;
    }
    if weap == WP_REPEATER {
        return 0.45;
    }
    if weap == WP_THERMAL {
        return 0.5;
    }
    if weap == WP_DEMP2 {
        return 0.35;
    }
    if weap == WP_ROCKET_LAUNCHER {
        return 0.7;
    }
    0.0
}

/// Raven `BotAimLeading`.
///
/// Source: `oracle/oracle/codemp/game/ai_main.c:4607-4684`
pub fn BotAimLeading(
    bs: *mut bot_state_t,
    headlevel: vec3_t,
    leadAmount: f32,
) {
    unsafe {
        let bs = &mut *bs;
        if bs.currentEnemy.is_none() || (*bs.currentEnemy).client.is_null() {
            return;
        }
        if bs.frame_Enemy_Len == 0.0 {
            return;
        }

        let ce_client = (*bs.currentEnemy).client;
        let vel = (*ce_client).ps.velocity;

        let mut vtotal: f32 = 0.0;
        if vel[0] < 0.0 { vtotal += -vel[0]; } else { vtotal += vel[0]; }
        if vel[1] < 0.0 { vtotal += -vel[1]; } else { vtotal += vel[1]; }
        if vel[2] < 0.0 { vtotal += -vel[2]; } else { vtotal += vel[2]; }

        let mut movement_vector = vel;
        crate::q_math::VectorNormalize(&mut movement_vector);

        // x is int in Raven; the first assignment (frame_Enemy_Len*leadAmount) is
        // a dead store, overwritten below. Raven's math promotes to double, then
        // truncates to int, so compute the magnitude in f64 to match.
        if vtotal > 400.0 {
            vtotal = 400.0;
        }
        let x: c_int = if vtotal != 0.0 {
            ((bs.frame_Enemy_Len as f64 * 0.9) * leadAmount as f64 * (vtotal as f64 * 0.0012))
                as c_int
        } else {
            ((bs.frame_Enemy_Len as f64 * 0.9) * leadAmount as f64) as c_int
        };

        let mut predicted_spot: vec3_t = [0.0; 3];
        predicted_spot[0] = headlevel[0] + (movement_vector[0] * x as f32);
        predicted_spot[1] = headlevel[1] + (movement_vector[1] * x as f32);
        predicted_spot[2] = headlevel[2] + (movement_vector[2] * x as f32);

        let mut a: vec3_t = [0.0; 3];
        a[0] = predicted_spot[0] - bs.eye[0];
        a[1] = predicted_spot[1] - bs.eye[1];
        a[2] = predicted_spot[2] - bs.eye[2];

        let mut ang: vec3_t = [0.0; 3];
        crate::q_math::vectoangles(a, &mut ang);
        bs.goalAngles = ang;
    }
}

