///
/// Source: `oracle/oracle/codemp/game/ai_main.c:5466-5481`
pub fn PrimFiring(
    bs: *mut bot_state_t,
) -> c_int {
    use mp_bg::public::weaponstate::weaponstate_t;
    unsafe {
        let bs = &*bs;
        if bs.cur_ps.weaponstate != weaponstate_t::WEAPON_CHARGING as c_int && bs.doAttack != 0 {
            return 1;
        }
        if bs.cur_ps.weaponstate == weaponstate_t::WEAPON_CHARGING as c_int && bs.doAttack == 0 {
            return 1;
        }
    }
    0
}

